import { useState } from "react";
import { motion, AnimatePresence } from "framer-motion";

const programs = [
  {
    title: "Weight Training",
    img: "https://images.unsplash.com/photo-1517836357463-d25dfeac3438",
    short:
      "Structured strength training focused on form, progression, and consistency.",
    long:
      "Weight Training at Bodyzeal Fitworks focuses on progressive resistance training aimed at improving strength, posture, and overall physical performance. Sessions emphasise correct movement patterns, gradual load progression, and safe training practices under trainer supervision.",
    branches: ["Nava India", "RS Puram", "Kovaipudur"],
  },
  {
    title: "Cardio Fitness",
    img: "https://images.unsplash.com/photo-1599058917212-d750089bc07e",
    short:
      "Planned cardio workouts designed to build endurance and stamina.",
    long:
      "Cardio Fitness programs are designed to improve cardiovascular endurance, stamina, and recovery using machine-based and functional training methods.",
    branches: ["Nava India", "RS Puram", "Kovaipudur"],
  },
  {
    title: "Personal Training",
    img: "https://images.unsplash.com/photo-1571019613454-1cb2f99b2d8b",
    short:
      "One-on-one coaching tailored to individual fitness goals.",
    long:
      "Personal Training offers customised workout programming with close trainer supervision. Each plan is designed around individual fitness levels, goals, and long-term consistency.",
    branches: ["Nava India", "RS Puram", "Kovaipudur"],
  },
  {
    title: "Zumba",
    img: "https://images.unsplash.com/photo-1549576490-b0b4831ef60a",
    short:
      "Dance-based cardio sessions focused on rhythm and endurance.",
    long:
      "Zumba sessions combine dance-based movements with cardio-focused routines to support endurance, coordination, and overall fitness in a group setting.",
    branches: ["Nava India"],
  },
  {
    title: "Group Training",
    img: "https://images.unsplash.com/photo-1518611012118-696072aa579a",
    short:
      "Coach-led group workouts designed for motivation and consistency.",
    long:
      "Group Training consists of structured coach-led workouts that build strength, conditioning, and long-term consistency through guided sessions.",
    branches: ["Nava India"],
  },
  {
    title: "Functional Training",
    img: "https://images.unsplash.com/photo-1550345332-09e3ac987658",
    short:
      "Movement-based training to improve strength, balance, and mobility.",
    long:
      "Functional Training focuses on real-world movement patterns that enhance strength, flexibility, balance, and injury prevention. Sessions are designed to improve overall physical performance and daily movement efficiency.",
    branches: ["Nava India", "RS Puram"],
  },
];

export default function Programs() {
  const [active, setActive] = useState(null);

  return (
    <section
      id="programs"
      className="bg-black text-white py-32 px-6 scroll-mt-28"
    >
      <div className="max-w-7xl mx-auto">

        {/* HEADING */}
        <div className="text-center max-w-3xl mx-auto mb-20">
          <h2 className="text-4xl md:text-5xl font-bold">
            Our <span className="text-red-600">Programs</span>
          </h2>
          <p className="mt-6 text-gray-400">
            Structured programs designed to support every fitness goal.
          </p>
        </div>

        {/* PROGRAM GRID */}
        <div className="grid sm:grid-cols-2 lg:grid-cols-3 gap-10">
          {programs.map((p, i) => (
            <motion.div
              key={i}
              whileHover={{ y: -8 }}
              transition={{ duration: 0.3 }}
              className="rounded-2xl overflow-hidden border border-white/10 bg-black shadow-xl"
            >
              <img
                src={`${p.img}?auto=format&fit=crop&w=900&q=80`}
                alt={p.title}
                className="h-56 w-full object-cover"
              />

              <div className="p-6 flex flex-col h-[230px]">
                <h3 className="text-xl font-semibold">{p.title}</h3>
                <p className="mt-3 text-sm text-gray-400 flex-1">
                  {p.short}
                </p>

                <button
                  onClick={() => setActive(p)}
                  className="mt-5 w-fit px-6 py-2 rounded-full border border-red-600 text-red-500 hover:bg-red-600 hover:text-white transition"
                >
                  View Details
                </button>
              </div>
            </motion.div>
          ))}
        </div>

        {/* FOOT NOTE */}
        <p className="mt-20 text-center text-sm text-gray-500 max-w-3xl mx-auto">
          Program availability is based on services offered at each branch.
          Only programs listed for a branch are available at that location.
        </p>
      </div>

      {/* PREMIUM MODAL */}
      <AnimatePresence>
        {active && (
          <motion.div
            className="fixed inset-0 z-50 bg-black/80 backdrop-blur flex items-center justify-center px-4"
            initial={{ opacity: 0 }}
            animate={{ opacity: 1 }}
            exit={{ opacity: 0 }}
          >
            <motion.div
              initial={{ scale: 0.9, y: 40 }}
              animate={{ scale: 1, y: 0 }}
              exit={{ scale: 0.9, y: 40 }}
              transition={{ duration: 0.3 }}
              className="relative max-w-4xl w-full bg-black border border-white/10 rounded-2xl overflow-hidden shadow-2xl grid md:grid-cols-2"
            >
              {/* CLOSE */}
              <button
                onClick={() => setActive(null)}
                className="absolute top-4 right-4 text-gray-400 hover:text-white z-10"
              >
                ✕
              </button>

              {/* IMAGE */}
              <div className="h-72 md:h-full">
                <img
                  src={`${active.img}?auto=format&fit=crop&w=900&q=80`}
                  alt={active.title}
                  className="w-full h-full object-cover"
                />
              </div>

              {/* CONTENT */}
              <div className="p-8">
                <h3 className="text-2xl font-bold mb-4">
                  {active.title}
                </h3>

                <p className="text-gray-400 text-sm leading-relaxed mb-6">
                  {active.long}
                </p>

                <h4 className="font-semibold mb-3">Available At</h4>

                <div className="space-y-3 text-sm">
                  {active.branches.map((branch, i) => (
                    <div
                      key={i}
                      className="flex justify-between items-center border-b border-white/10 pb-2"
                    >
                      <span>{branch} Branch</span>
                      <button className="text-red-500 hover:underline">
                        View Pricing
                      </button>
                    </div>
                  ))}
                </div>
              </div>
            </motion.div>
          </motion.div>
        )}
      </AnimatePresence>
    </section>
  );
}
